window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-13ddf351067dd5fb"]={"versions": [{"id": "FIG-13ddf351067dd5fb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurations-Metamodell (UML-Klassendiagramm). Das Diagramm spezifiziert die Konfigurationsstruktur des Moduls <code>EthSwt</code> (Ethernet Switch Driver) für die Interaktion mit dem Basissoftware-Modul <code>NvM</code> (Non-Volatile RAM Manager) zur dauerhaften Speicherung von Konfigurations- und Tabellendaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>EthSwtConfig</strong> (<code>EcucParamConfContainerDef</code>): Wurzelkonfigurationscontainer des Switch-Treibers mit Multiplizität <code>1..*</code>.\n</li><li><strong>EthSwtNvm</strong> (<code>EcucParamConfContainerDef</code>): Subcontainer unterhalb von <code>EthSwtConfig</code> (Rolle <code>+subContainer</code>, Multiplizität <code>0..1</code>).\n</li><li><strong>EthSwtNvmBlockDescriptorRef</strong> (<code>EcucSymbolicNameReferenceDef</code>): Referenzdefinition innerhalb von <code>EthSwtNvm</code> (Rolle <code>+reference</code>), verweist per <code>+destination</code> auf <code>NvMBlockDescriptor</code>.\n</li><li><strong>NvMBlockDescriptor</strong> (<code>EcucParamConfContainerDef</code>, aus Modul <code>NvM</code>): Zielcontainer mit Multiplizität <code>1..65536</code>.\n</li><li><strong>NvMNvramBlockIdentifier</strong> (<code>EcucIntegerParamDef</code>): Parameter innerhalb von <code>NvMBlockDescriptor</code> (Rolle <code>+parameter</code>) mit <code>symbolicNameValue = true</code>, Wertebereich <code>min = 2</code> bis <code>max = 65535</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Konfigurationsabfolge bei der BSW-Generierung: Eine Instanz von <code>EthSwtNvm</code> adressiert über die symbolische Referenz <code>EthSwtNvmBlockDescriptorRef</code> einen projektspezifischen NVRAM-Block des NvM-Treibers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration von <code>EthSwtNvm</code> ist optional (<code>lowerMultiplicity = 0</code>). Sofern nichtflüchtige Speicherung im Switch-Treiber verwendet wird, ist die Referenz <code>EthSwtNvmBlockDescriptorRef</code> verpflichtend an einen gültigen <code>NvMBlockDescriptor</code> zu binden. Der Ziel-NVRAM-Block muss einen symbolischen Namen besitzen (<code>symbolicNameValue = true</code>), dessen numerischer Identifier innerhalb des Intervalls [2, 65535] liegt (Reservierung der Werte 0 und 1 für interne NvM-Zwecke).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-65415e453f8faf77", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurations-Metamodell (UML-Klassendiagramm). Das Diagramm spezifiziert die Konfigurationsstruktur des Moduls <code>EthSwt</code> (Ethernet Switch Driver) für die Interaktion mit dem Basissoftware-Modul <code>NvM</code> (Non-Volatile RAM Manager) zur dauerhaften Speicherung von Konfigurations- und Tabellendaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>EthSwtConfig</strong> (<code>EcucParamConfContainerDef</code>): Wurzelkonfigurationscontainer des Switch-Treibers mit Multiplizität <code>1..*</code>.\n</li><li><strong>EthSwtNvm</strong> (<code>EcucParamConfContainerDef</code>): Subcontainer unterhalb von <code>EthSwtConfig</code> (Rolle <code>+subContainer</code>, Multiplizität <code>0..1</code>).\n</li><li><strong>EthSwtConfigurationNvmBlockDescriptorRef</strong> (<code>EcucReferenceDef</code>): Referenzdefinition innerhalb von <code>EthSwtNvm</code> (Rolle <code>+reference</code>) mit <code>requiresSymbolicNameValue = true</code>, verweist per <code>+destination</code> auf <code>NvMBlockDescriptor</code>.\n</li><li><strong>EthSwtTableNvmBlockDescriptorRef</strong> (<code>EcucReferenceDef</code>): Zweite Referenzdefinition innerhalb von <code>EthSwtNvm</code> (Rolle <code>+reference</code>) mit <code>requiresSymbolicNameValue = true</code>, verweist per <code>+destination</code> auf <code>NvMBlockDescriptor</code>.\n</li><li><strong>NvMBlockDescriptor</strong> (<code>EcucParamConfContainerDef</code>, aus Modul <code>NvM</code>): Zielcontainer mit Multiplizität <code>1..65536</code>.\n</li><li><strong>NvMNvramBlockIdentifier</strong> (<code>EcucIntegerParamDef</code>): Parameter innerhalb von <code>NvMBlockDescriptor</code> (Rolle <code>+parameter</code>) mit <code>symbolicNameValue = true</code>, Wertebereich <code>min = 2</code> bis <code>max = 65535</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Konfigurationsabfolge bei der BSW-Generierung: Eine Instanz von <code>EthSwtNvm</code> adressiert über die symbolische Referenz <code>EthSwtNvmBlockDescriptorRef</code> einen projektspezifischen NVRAM-Block des NvM-Treibers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration von <code>EthSwtNvm</code> ist optional (<code>lowerMultiplicity = 0</code>). Sofern nichtflüchtige Speicherung genutzt wird, müssen getrennte NvM-Blöcke für Konfigurationsdaten (<code>EthSwtConfigurationNvmBlockDescriptorRef</code>) und Tabellendaten/MAC-Adress-Tabellen (<code>EthSwtTableNvmBlockDescriptorRef</code>) referenziert werden. Beide Referenzen fordern zwingend Zielblöcke mit symbolischem Namen (<code>requiresSymbolicNameValue = true</code>), deren <code>NvMNvramBlockIdentifier</code> im Wertebereich von 2 bis 65535 liegt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-13ddf351067dd5fb", "to": "FIG-65415e453f8faf77", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Referenz <code>EthSwtNvmBlockDescriptorRef</code> vom Metatyp <code>EcucSymbolicNameReferenceDef</code> wird aufgeteilt in zwei getrennte Referenzen: <code>EthSwtConfigurationNvmBlockDescriptorRef</code> und <code>EthSwtTableNvmBlockDescriptorRef</code>.\n</li><li>Metatyp beider Referenzen ist nun <code>EcucReferenceDef</code> mit der Eigenschaft <code>requiresSymbolicNameValue = true</code>.\n</li><li>Beide Referenzen verweisen unabhängig voneinander per <code>+destination</code> auf den Zielcontainer <code>NvMBlockDescriptor</code>.\n</li></ul>"}]};
